from pathlib import Path
p=Path(__file__).with_name('index.html');s=p.read_text()
s=s.replace('Contributions au téléphone validées','Vues au sol datées · flammes / fumée').replace('Aperçus satellites de contexte','Couples Sentinel‑2 traités')
s=s.replace('La sélection photographique précédente a été retirée : elle ne représente pas les contributions attendues au téléphone depuis le sol. Aucun lot de contributions n’est encore validé.','Les vues retenues viennent de témoins, des secours et de la presse. Leur point de vue est comparable à un téléphone ; l’appareil reste inconnu. Les 14 anciennes photos restent écartées.')
s=s.replace('<h3>Contexte satellite — distinct des contributions</h3>','<h3>Branche visuelle au sol</h3><div class="media" id="ground"></div><details><summary>Cas difficiles / après-feu</summary><div class="media" id="difficult"></div></details><h3>Branche Sentinel‑2 · changement optique</h3><div id="optical"></div><h3>Branche thermique · points chauds</h3><p id="thermal"></p><details><summary>Aperçus NASA / Copernicus pour l’affichage</summary>')
s=s.replace('<div class="media" id="media"></div>','<div class="media" id="media"></div></details>')
s=s.replace('Aucune annotation flamme/fumée ni géométrie n’a encore été produite par le pipeline pour ce dossier.','Les sorties optiques soutiennent l’analyse des zones affectées. Elles ne sont ni un front actif, ni le périmètre final. La comparaison complète actuel / TypeSafe reste à exécuter.')
s=s.replace('</main>','<section class="panel wide"><h2>Vues utiles dont le jour reste à préciser</h2><p id="review-summary"></p><details><summary>Ouvrir la sélection sans date résolue</summary><div class="media" id="uncertain"></div></details><p><a href="acquisition/field-reviewed/review.json" target="_blank">Décisions de tri</a></p></section><section class="panel wide"><h2>Vidéo · scènes et dates</h2><div id="videos"></div><p>Plusieurs images de la même vidéo conservent une seule provenance. Les extractions de contrôle ne sont pas des résultats de détection.</p></section></main>')
s=s.replace('</style>','details{margin:16px 0}summary{cursor:pointer;padding:12px 0}.pair{border-top:1px solid #334254;padding:14px 0}.pair img,video{max-width:100%;max-height:430px}.row a{overflow-wrap:anywhere}.columns>*{min-width:0}</style>')
s=s[:s.index('<script>')]+'''<script>
let current='2025-08-05',report;
const el=id=>document.getElementById(id);
const names={official_daily_report:'Rapport officiel',ground_image:'Vue au sol',satellite_browse:'Aperçu NASA',satellite_quicklook:'Aperçu Copernicus',satellite_multispectral:'Bandes Sentinel‑2'};
function node(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
function link(text,url){const a=node('a',text);a.href=url;a.target='_blank';a.rel='noreferrer';return a}
function gallery(id,items){el(id).replaceChildren(...items.map(s=>{const f=node('figure'),im=node('img');im.src=s.path;im.alt=s.review_note||names[s.kind];im.loading='lazy';const c=node('figcaption',s.review_note||names[s.kind]);c.append(node('span',s.provider||'','meta'),node('span',s.local_date?'Capture : '+s.local_date+(s.capture_day_inferred?' · contexte du reportage':' · légende datée'):'Jour de capture non résolu','meta'));if(s.published_at)c.append(node('span','Publication : '+s.published_at.slice(0,10),'meta'));c.append(link('Original',s.path),node('span',' · '),link('Provenance',s.source_url));f.append(im,c);return f}));if(!items.length)el(id).append(node('p','Aucune image admise dans cette catégorie.'))}
function render(){
 const good=report.sources.filter(s=>s.file_verified),positive=good.filter(s=>s.role==='positive_ground_scene'),unknown=good.filter(s=>s.role==='visual_candidate_day_unresolved');
 el('period').textContent=report.incident+' · 5–9 août 2025 · Europe/Paris';el('documents').textContent=good.filter(s=>s.kind==='official_daily_report').length;el('pictures').textContent=positive.length;el('satellites').textContent=report.branches.sentinel2_optical_change.unique_pairs;
 el('days').replaceChildren(...report.days.map(d=>{const b=node('button',d.date.slice(8)+' août');b.setAttribute('aria-pressed',d.date===current);b.onclick=()=>{current=d.date;render()};return b}));
 const items=good.filter(s=>s.local_date===current);el('day-title').textContent='Sources disponibles · '+current;el('day-summary').textContent=items.filter(s=>s.kind==='official_daily_report').length+' rapports officiels · '+items.filter(s=>s.role==='positive_ground_scene').length+' vues positives datées. Une famille absente ne bloque pas la journée.';
 gallery('ground',items.filter(s=>s.role==='positive_ground_scene'));gallery('difficult',items.filter(s=>s.role==='difficult_or_negative'));gallery('uncertain',unknown);gallery('media',items.filter(s=>['satellite_browse','satellite_quicklook'].includes(s.kind)));
 el('review-summary').textContent=(report.review.visual_reviewed||0)+' images examinées · '+unknown.length+' vues utiles dont le jour reste incertain · '+good.filter(s=>s.role==='difficult_or_negative').length+' cas difficiles / après-feu. Couverture quotidienne encore inégale ; représentativité non validée.';
 const pairs=report.branches.sentinel2_optical_change.pairs.filter(p=>p.daily_cutoffs.includes(current));el('optical').replaceChildren(node('p',pairs.length?(current==='2025-08-07'?'Passage du 7 août, comparé au 4 août.':'Même passage du 7 août réutilisé ; ce ne sont pas de nouvelles observations.'):'Aucun couple avant/après admissible à cette échéance.'),...pairs.map(p=>{const d=node('div',null,'pair');d.append(node('strong',p.post_item_id),node('p','Résolution effective '+p.resolution_m+' m · grille de cette tuile : '+(p.metrics.valid_fraction*100).toFixed(1)+' % valides, '+(p.metrics.cloud_fraction*100).toFixed(1)+' % nuageux, '+(p.metrics.no_data_fraction*100).toFixed(1)+' % sans données.'));if(p.preview_path){const im=node('img');im.src=p.preview_path;im.alt='Observations optiques avant et après';d.append(im)}d.append(link('Résultat réel du processeur',p.first_result_path));for(const f of p.files)d.append(node('p'),link(f.path,p.first_result_path.replace(/[^/]+$/,f.path)));return d}));
 el('thermal').textContent=report.branches.thermal_activity.detail||'Mesures historiques non acquises : accès NASA FIRMS / CDSE à configurer. Les requêtes publiques EFFIS n’ont pas fourni d’observations ; cela ne signifie pas absence de points chauds. Les aperçus ne remplacent pas les mesures.';
 el('sources').replaceChildren(...items.filter(s=>s.role!=='excluded_candidate').map(s=>{const d=node('div',null,'row');d.append(link(names[s.kind]||s.id,s.path),node('span','SHA-256 vérifié','tag'));return d}));
 el('results').replaceChildren(...report.days.map(d=>{const tr=node('tr');[d.date,'Non exécuté','Non exécuté','—'].forEach(t=>tr.append(node('td',t)));return tr}));el('blockers').replaceChildren(...report.runtime.blockers.map(t=>node('p',t)));
 el('searches').replaceChildren(...report.searches.map(s=>{const d=node('div',null,'row'),c=node('div');c.append(node('strong',s.family),node('p',s.detail));d.append(c);return d}));
 el('videos').replaceChildren(...report.videos.map(v=>{const d=node('div'),player=node('video');player.controls=true;player.preload='none';player.src=v.path;d.append(player,node('p',v.review_note||'Scènes en cours de vérification.'),link('Provenance',v.source_url));return d}));
 el('updated').textContent='Inventaire : '+new Date(report.updated_at).toLocaleString('fr-FR')+' · Relu toutes les 5 s · Arrêt AWS : '+new Date(report.constraints.aws_stop_at).toLocaleString('fr-FR',{timeZone:'Europe/Paris'})+' (Paris).';
}
async function update(){try{const r=await fetch('inventory.json',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const v=await r.json();if(!report||v.updated_at!==report.updated_at){report=v;render()}el('failure').textContent=''}catch(e){el('failure').textContent='Inventaire indisponible : '+e.message}
try{const r=await fetch('acquisition/expanded/manifest.json',{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json(),n=d.pages.filter(p=>p.status==='downloaded').length;el('discovery').textContent=(d.complete?'Vague terminée':'Collecte en cours')+' · '+d.pages.length+'/'+d.planned_pages+' pages tentées · '+n+' récupérées · '+(d.pages.length-n)+' échecs · '+d.media.length+' médias candidats';el('discovery-detail').textContent='Les médias candidats incluent des doublons et des archives. Seules les décisions de tri alimentent les compteurs de sélection.'}catch{el('discovery').textContent='Journal du collecteur momentanément indisponible.'}}
update();setInterval(update,5000);
</script></html>
'''
p.write_text(s)
